import{_ as a}from"./chunks/00-sidebar-overview.CFI0fTnD.js";import{_ as t}from"./chunks/12-audit.CWIaVMMc.js";import{_ as r,o as s,c as o,a3 as i}from"./chunks/framework.BGhsAJMQ.js";const _=JSON.parse('{"title":"安全与敏感文件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/features/security.md","filePath":"zh/features/security.md","lastUpdated":1793949581000}'),n={name:"zh/features/security.md"};function l(h,e,d,c,p,u){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="安全与敏感文件" tabindex="-1">安全与敏感文件 <a class="header-anchor" href="#安全与敏感文件" aria-label="Permalink to &quot;安全与敏感文件&quot;">​</a></h1><p>filebox 的默认姿态是：<strong>浏览只读、路径牢笼、敏感文件拒绝</strong>。Transfer 仅写入专用临时目录。AI Agents 通过独立的白名单后端管理编码代理。</p><p><img src="'+a+`" alt="侧栏能力入口"></p><h2 id="只读协议" tabindex="-1">只读协议 <a class="header-anchor" href="#只读协议" aria-label="Permalink to &quot;只读协议&quot;">​</a></h2><p>浏览路径没有写 / 删 / 重命名 / 任意 exec 消息。</p><table tabindex="0"><thead><tr><th>例外</th><th>作用域</th><th>防护</th></tr></thead><tbody><tr><td><strong>Transfer</strong></td><td>仅 Agent 专用 scratch 目录</td><td>配额、禁覆盖、不作为普通 root</td></tr></tbody></table><h2 id="敏感文件默认拒绝-节选" tabindex="-1">敏感文件默认拒绝（节选） <a class="header-anchor" href="#敏感文件默认拒绝-节选" aria-label="Permalink to &quot;敏感文件默认拒绝（节选）&quot;">​</a></h2><p>即使根目录已授权，匹配项仍不可读：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.git/  .ssh/  .gnupg/  .aws/  .kube/</span></span>
<span class="line"><span>.env*  *.pem  *.key  id_*  credentials*.json  *.sqlite*</span></span></code></pre></div><p>以及 shell history 等常见凭证位置。具体规则以当前版本实现为准。</p><h2 id="路径牢笼" tabindex="-1">路径牢笼 <a class="header-anchor" href="#路径牢笼" aria-label="Permalink to &quot;路径牢笼&quot;">​</a></h2><p>浏览严格限制在已添加的 root 内；<code>..</code>、符号链接逃逸等会被挡住。</p><h2 id="认证与信任" tabindex="-1">认证与信任 <a class="header-anchor" href="#认证与信任" aria-label="Permalink to &quot;认证与信任&quot;">​</a></h2><ul><li>用户登录在 Hub（PoW + 会话 cookie + CSRF）。</li><li>每台机器用独立 Agent token（Hub 只存 hash）。</li><li>Agent 出站连 Hub；目标机无需入站。</li><li>生产环境务必 HTTPS，保护 token 与会话。</li><li>登录事件见侧栏 <strong>Audit</strong>。</li></ul><p><img src="`+t+'" alt="登录审计"></p><h2 id="架构向说明" tabindex="-1">架构向说明 <a class="header-anchor" href="#架构向说明" aria-label="Permalink to &quot;架构向说明&quot;">​</a></h2><p>更底层的 Hub↔Agent 信任边界、token、限流等见仓库内开发文档 <a href="https://github.com/ZhimingYe/filebox/blob/main/docs/hub-agent-security-model.md" target="_blank" rel="noreferrer"><code>docs/hub-agent-security-model.md</code></a>（中文）。</p><h2 id="ai-agents-与提示词审核" tabindex="-1">AI Agents 与提示词审核 <a class="header-anchor" href="#ai-agents-与提示词审核" aria-label="Permalink to &quot;AI Agents 与提示词审核&quot;">​</a></h2><p>AI Agents 不是只读文件预览：编码代理可执行操作、修改文件，不受浏览 root 限制。提示词默认先由 Hub 的 LLM 审核，阻止破坏性命令、永久删除和提取密钥，允许正常数据分析与开发。审核器会看到提示词及目标窗口近期输出；未配置或审核失败时拒绝发送，草稿保留。状态、读取输出与白名单按键仍可用，按键不经 LLM 审核。管理员可在 Hub 启动时显式关闭审核。见 <a href="/filebox/zh/ops/hub#prompt-review-ai-agents">提示词审核</a>。</p>',19)])])}const f=r(n,[["render",l]]);export{_ as __pageData,f as default};
